 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // --------- Schedule for initialization ---------
    // Use a reasonable SIMD width for the current host and type.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Initialize x in parallel and vectorized over the innermost chunk of i.
    {
        Var io("io"), ii("ii");
        init_x
            .compute_root()
            .split(i, io, ii, 1024)   // tiles of 1024 elements
            .vectorize(ii, vec_width)
            .parallel(io);
    }

    // Initialize A and B with 2D tiling for good cache locality:
    // tile over (j, i) so that j (columns, contiguous in memory) is
    // the innermost, vectorized dimension.
    {
        const int tile_j = 32;
        const int tile_i = 32;

        Var jo("jo"), ji("ji"), io("io"), ii("ii");

        init_A
            .compute_root()
            // Tiles: (j, i) -> (jo, io, ji, ii)
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            // Make ji (fast j coordinate) innermost so accesses are unit-stride.
            .reorder(ji, ii, jo, io)
            .vectorize(ji, vec_width)
            .parallel(io);

        init_B
            .compute_root()
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            .reorder(ji, ii, jo, io)
            .vectorize(ji, vec_width)
            .parallel(io);
    }
    // ------------------------------------------------

    // Realize the initialization Funcs into the user-provided Buffers.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Express that the first dimension is contiguous in memory.
    // This helps Halide generate better vectorized memory accesses.
    A_param.dim(0).set_stride(1);
    B_param.dim(0).set_stride(1);
    x_param.dim(0).set_stride(1);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns (fast dimension of A, B).
    RDom j(0, A.dim(0).extent(), "j");

    // tmp[i] = sum_j A[i][j] * x[j]
    // y_acc[i] = sum_j B[i][j] * x[j]
    // y[i] = alpha * tmp[i] + beta * y_acc[i]
    Func tmp("tmp"), y_acc("y_acc"), y_func("y_func");

    // Initialize reductions.
    tmp(i)    = cast<num_t>(0);
    y_acc(i)  = cast<num_t>(0);

    // Reduction over j (dot products for each i).
    tmp(i)   += A_param(j, i) * x_param(j);
    y_acc(i) += B_param(j, i) * x_param(j);

    // Final combination.
    y_func(i) = Expr(alpha) * tmp(i) + Expr(beta) * y_acc(i);

    // --------- Schedule for the GESUMMV kernel ---------

    // Use host target information to choose a sensible SIMD width.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Parallelize across rows i (each row's dot products are independent).
    // We tile i to create reasonably sized chunks per thread.
    {
        Var io("io"), ii("ii");
        y_func
            .compute_root()
            .split(i, io, ii, 128)  // tiles of 128 rows
            .parallel(io);
        // We deliberately do NOT vectorize across i because that
        // would involve strided accesses to A/B. Instead, we keep
        // i scalar and encourage vectorization over j inside tmp/y_acc.
    }

    // Compute the per-row dot products close to where y_func is computed,
    // so that their storage can stay in registers / L1.
    {
        // Compute each tmp(i) and y_acc(i) within the inner i-tile loop.
        Var ii("ii"); // reuse the same ii as in y_func schedule
        tmp.compute_at(y_func, ii);
        y_acc.compute_at(y_func, ii);

        // Unroll the reduction over j a bit to reduce loop overhead and
        // help the compiler generate efficient scalar or SIMD code.
        // We keep the reduction sequential to avoid race conditions.
        tmp.update().unroll(j, 4);
        y_acc.update().unroll(j, 4);
    }
    // ---------------------------------------------------

    // Compile the kernel to machine code.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
