    // ------------------------------------------------------------------
    // Scheduling for the initialization pipeline
    // ------------------------------------------------------------------
    //
    // We parallelize across rows (i) and vectorize across the
    // contiguous column dimension (j) for A and B, and across i
    // for x. This improves cache use and makes better use of SIMD.
    //
    // Note: we only care about speeding up initialization slightly;
    // the main focus is the GESUMMV kernel below.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Vectorize x over its single dimension and parallelize it if large.
    init_x
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    // For A and B, j is the unit-stride dimension (dim 0), so we
    // vectorize across j and parallelize across i (rows).
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_B
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

