    init_x.realize(x, target);
    init_A.realize(A, target);
    init_B.realize(B, target);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    RDom j(0, n, "j");  // j runs over columns (fast dimension)

    // ------------------------------------------------------------------
    // GESUMMV computation:
    //
    //   tmp[i]    = sum_j A[i][j] * x[j]
    //   y_acc[i]  = sum_j B[i][j] * x[j]
    //   y[i]      = alpha * tmp[i] + beta * y_acc[i]
    //
    // In C, this is typically written with a single inner loop with
    // two accumulators. We mirror that using a Tuple so that both
    // dot products share the same traversal over j, improving cache
    // locality vs doing two separate reductions.
    // ------------------------------------------------------------------

    // acc(i) is a 2-element tuple:
    //   acc(i)[0] = tmp[i]
    //   acc(i)[1] = y_acc[i]
    Func acc("acc"), y_func("y_func");

    // Pure definition: initialize both accumulators to zero.
    acc(i) = Tuple(cast<num_t>(0), cast<num_t>(0));

    // Reduction over j: accumulate both sums in one pass over A, B, x.
    acc(i) = Tuple(acc(i)[0] + A_param(j, i) * x_param(j),
                   acc(i)[1] + B_param(j, i) * x_param(j));

    // Final combination: y[i] = alpha * tmp[i] + beta * y_acc[i]
    Expr alpha_e = cast<num_t>(alpha);
    Expr beta_e  = cast<num_t>(beta);

    y_func(i) = alpha_e * acc(i)[0] + beta_e * acc(i)[1];

    // ------------------------------------------------------------------
    // Scheduling the GESUMMV pipeline
    // ------------------------------------------------------------------
    //
    // Layout recap:
    //   A(j, i), B(j, i): j is unit-stride (columns), i is rows.
    //   x(j): j is unit-stride.
    //   y(i): rows.
    //
    // We want to:
    //   - Parallelize across rows (i), which are independent.
    //   - Vectorize across chunks of rows (ii) for better ILP, even
    //     though this implies strided loads for A/B in memory. The
    //     dot-product over j remains scalar but benefits from cache.
    //   - Keep the reduction over j sequential per (i) to avoid
    //     tricky reduction-factorization, ensuring correctness.
    //
    // We also introduce a tunable tile size in i for good cache use.
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    // Tile size along i; can be tuned for a given machine.
    const int i_tile = 128;

    Var io("io"), ii("ii");

    // Schedule for the tuple-valued reduction acc(i).
    // Pure step: initialize acc(i) over all i.
    acc
        .compute_root()
        .split(i, io, ii, i_tile)   // i = io * i_tile + ii
        .parallel(io)               // parallelize tiles of rows
        .vectorize(ii, vec_width);  // SIMD within a tile over ii

    // Update step: the reduction over j for each i.
    // After the split above, the reduction loops are over (io, ii, j).
    // We reuse the same parallelization and vectorization over i.
    acc.update()
        .parallel(io)
        .vectorize(ii, vec_width);
        // We keep j purely serial here for strict correctness
        // without needing rfactor; each (i) reduction is sequential.

    // Schedule for y_func: purely pointwise in i, very cheap compared
    // to acc, but we mirror the tiling/parallelism to keep structure.
    y_func
        .compute_root()
        .split(i, io, ii, i_tile)
        .parallel(io)
        .vectorize(ii, vec_width);

    // Compile the kernel to machine code for the chosen target.
    y_func.compile_jit(target);

    // Measure execution time (only the GESUMMV kernel).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
