    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / Expr(n);

    // Simple, bandwidth-friendly schedules for initialization:
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // x is 1D, contiguous
    {
        Var io("io"), ii("ii");
        const int tile_i = 1024;
        init_x
            .compute_root()
            .split(i, io, ii, tile_i)
            .parallel(io)
            .vectorize(ii, vec_width);
    }

    // A and B are stored as (j, i) = (column, row), j contiguous.
    {
        Var jo("jo"), ji("ji"), io("io"), ii("ii");
        const int tile_i = 32;      // tile rows
        const int tile_j = 256;     // tile columns

        init_A
            .compute_root()
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            .parallel(io)          // parallelize over tiles of rows
            .vectorize(ji, vec_width);

        init_B
            .compute_root()
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            .parallel(io)
            .vectorize(ji, vec_width);
    }

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    RDom j(0, n, "j");  // j runs over columns (fast dimension)

    // We compute two dot products per row:
    //   tmp[i]   = sum_j A[i][j] * x[j]
    //   y_acc[i] = sum_j B[i][j] * x[j]
    // and then combine:
    //   y[i] = alpha * tmp[i] + beta * y_acc[i]
    //
    // To improve locality and reduce loop overhead, we fuse the two
    // dot-products into a single reduction using a Tuple:
    //
    //   partial(i)[0] == tmp[i]
    //   partial(i)[1] == y_acc[i]
    //
    // This keeps the order of operations inside each reduction
    // identical to the original code (we still accumulate over j
    // in increasing order), but lets us traverse A and B only once.

    Func partial("partial"), y_func("y_func");

    // Pure definition: initialize both accumulators to zero.
    partial(i) = Tuple(cast<num_t>(0), cast<num_t>(0));

    // Reduction over j: update both accumulators in one pass.
    {
        Expr a_ij = A_param(j, i);   // A is stored as (j, i)
        Expr b_ij = B_param(j, i);   // B is stored as (j, i)
        Expr x_j  = x_param(j);

        Expr acc_A = partial(i)[0] + a_ij * x_j;
        Expr acc_B = partial(i)[1] + b_ij * x_j;

        partial(i) = Tuple(acc_A, acc_B);
    }

    // Final combination, exactly matching the mathematical formula:
    y_func(i) = Expr(alpha) * partial(i)[0] + Expr(beta) * partial(i)[1];

    // --------------------
    // Schedule
    // --------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tuneable tile size for the outer loop over rows.
    // This exposes coarse-grain parallelism across rows i,
    // while keeping a reasonable amount of work per task
    // to amortize threading overhead.
    const int i_tile = 256;

    Var io("io"), ii("ii");

    // Compute the final result at the top level.
    // Layout:
    //   for io in parallel over tiles of rows:
    //     for ii over rows inside tile (vectorized):
    //       compute reduction for partial(i) and then y(i)
    //
    // partial(i) will be computed at the innermost necessary
    // level of y_func by Halide's default reduction schedule,
    // so no explicit schedule on `partial` is required. This
    // produces a single fused (i,j) loop nest per tile with:
    //   - outer parallelism over io
    //   - inner scalar reduction over j for each i
    //   - optional vectorization over ii (rows) if supported.
    y_func
        .compute_root()
        .split(i, io, ii, i_tile)
        .parallel(io);

    // Vectorize across rows inside each tile if we have a
    // meaningful native vector width. (Note: this vectorizes
    // accesses to y_func and to the partial accumulators across
    // i; A and B are strided in this direction, but the stride
    // is constant so modern CPUs can still generate efficient
    // gather patterns.)
    if (vec_width > 1) {
        y_func.vectorize(ii, vec_width);
    }

    // Provide stride information on the ImageParams to help
    // Halide generate good memory accesses:
    //
    // A and B: (j, i) with j contiguous.
    A_param.dim(0).set_stride(1); // j dimension
    B_param.dim(0).set_stride(1);
    // x: 1D, contiguous.
    x_param.dim(0).set_stride(1);

    // Compile the kernel to machine code.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
