int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns – dim(0) is the fast (column) dimension.
    RDom j(0, A.dim(0).extent(), "j");

    // tmp[i]   = sum_j A[i][j] * x[j]
    // y_acc[i] = sum_j B[i][j] * x[j]
    // y[i]     = alpha * tmp[i] + beta * y_acc[i]
    Func tmp("tmp"), y_acc("y_acc"), y_func("y_func");

    // Initialize reductions.
    tmp(i)   = cast<num_t>(0);
    y_acc(i) = cast<num_t>(0);

    // Reduction over j (matrix–vector products).
    tmp(i)   += A_param(j, i) * x_param(j);
    y_acc(i) += B_param(j, i) * x_param(j);

    // Final combination (pure stage).
    y_func(i) = Expr(alpha) * tmp(i) + Expr(beta) * y_acc(i);

    // ------------------------------------------------------------------
    // Scheduling for the GESUMMV pipeline
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int i_tile = 256;  // tunable tile size along i (rows)

    // We want:
    //  - parallelism across rows i,
    //  - vectorization across columns j (fast dimension) inside the reductions,
    //  - a simple, cache-friendly traversal: for a fixed row i, j sweeps
    //    linearly over the contiguous column dimension.

    // Schedule for tmp (A * x).
    {
        RVar jo("jo"), ji("ji");

        // Parallelize across rows; each thread computes independent dot products.
        tmp.compute_root()
            .parallel(i);

        // In the reduction, split j into a vectorized inner loop ji.
        // Layout is A(j, i), so stepping in j is contiguous in memory.
        tmp.update()
            .split(j, jo, ji, vec_width)  // j = jo * vec_width + ji
            .vectorize(ji)                // operate on vec_width columns at once
            .parallel(i);                 // rows i are independent
    }

    // Schedule for y_acc (B * x).
    {
        RVar ko("ko"), ki("ki");

        y_acc.compute_root()
             .parallel(i);

        y_acc.update()
             .split(j, ko, ki, vec_width)
             .vectorize(ki)
             .parallel(i);
    }

    // Schedule for the final combination y_func.
    {
        Var io("io"), ii("ii");

        // Simple, bandwidth-light combination. We tile i so that
        // we can parallelize outer tiles and vectorize within each tile.
        y_func
            .compute_root()
            .split(i, io, ii, i_tile)
            .parallel(io)          // tiles of rows in parallel
            .vectorize(ii, vec_width);
    }

    // Compile the kernel to machine code for the host.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
